CREATE TABLE document_records (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  payload JSON NOT NULL,
  payload_type VARCHAR(32) GENERATED ALWAYS AS (JSON_UNQUOTE(JSON_EXTRACT(payload, '$.type'))) VIRTUAL,
  payload_hash BINARY(32) GENERATED ALWAYS AS (UNHEX(SHA2(CAST(payload AS CHAR), 256))) STORED,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='document records';
